//
// What every generated form shares: putting a value into a control tree whose
// repeatable fields are arrays of controls, reading the value back in its
// wire form, and binding a server `request-validation` problem's field errors
// onto the controls they name. A field-error path is dot-separated wire names
// relative to the body, array elements as `[n]` -- the one path rule every
// backend realizes.

import {
  type AbstractControl,
  FormArray,
  FormGroup,
  type ValidationErrors,
  type ValidatorFn,
} from '@angular/forms';

import { ValidationError, type FieldError } from '@lanternpost/system-api-common';

/** Builds one new item of a repeatable field. */
export type ItemFactory = () => AbstractControl;

/**
 * The paths of a form's repeatable fields, date-time fields, and fields the
 * body leaves out when unset: `items`, `items[].tags` (an element of `items`,
 * then its `tags`), `placedAt`.
 *
 * `omitWhenUnset` names non-nullable fields the server needs no value for --
 * a declared default it applies, or an update's unchanged stored value -- so
 * an empty control there is left out of the body rather than sent as null,
 * which the server would reject.
 */
export interface FormShape {
  readonly items: Readonly<Record<string, ItemFactory>>;
  readonly dateTimes: ReadonlySet<string>;
  readonly omitWhenUnset: ReadonlySet<string>;
}

/** The text a form shows: one message per key, its placeholders filled from *args*. */
export interface FormMessages {
  key(messageKey: string, args?: Readonly<Record<string, unknown>>): { readonly text: string };
}

/** How a form shows a number, an amount, a percentage, a date, a date-time and a time in the user's locale. */
export interface FormFormat {
  number(value: number | string): string;
  money(value: number | string): string;
  minorMoney(minorUnits: number | string, currency: string): string;
  percent(value: number | string): string;
  date(value: Date | string): string;
  dateTime(value: Date | string): string;
  time(value: Date | string): string;
}

/**
 * A text control's length bound in code points, as every target counts a
 * `String(n)` field's length (`Validators.minLength`/`maxLength` count UTF-16
 * code units, so an emoji would count twice). An empty value passes, as with
 * Angular's own length validators; `Validators.required` judges emptiness. The
 * error keys are Angular's (`minlength`/`maxlength`).
 */
