    const value: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(control.controls)) {
      if (child.disabled) {
        continue;
      }
      const childAt = childPath(path, key);
      const childValue = formValueForWire(child, shape, childAt);
      if (shape.omitWhenUnset.has(childAt) && (childValue === null || childValue === '')) {
        continue;
      }
      value[key] = childValue;
    }
